package com.andye.warmod.antiair;import com.andye.warmod.icbm.IcbmTrajectory;import java.util.Optional;import net.minecraft.world.phys.Vec3;public final class AntiAirInterceptSolver{private AntiAirInterceptSolver(){}public static Optional<AntiAirInterceptSolution> solve(Vec3 burnout,long burnoutTime,AntiAirTargetLock lock){long last=Math.min(burnoutTime+AntiAirConstants.MAXIMUM_INTERCEPT_LOOKAHEAD_TICKS,lock.separationGameTime()+AntiAirConstants.SEPARATION_INTERCEPT_GRACE_TICKS);for(long time=burnoutTime+AntiAirConstants.MINIMUM_INTERCEPT_LEAD_TICKS;time<=last;time+=AntiAirConstants.INTERCEPT_SAMPLE_STEP_TICKS){double targetElapsed=time-lock.carrierPlan().launchGameTime();Vec3 target=IcbmTrajectory.position(lock.carrierPlan(),targetElapsed),velocity=IcbmTrajectory.velocity(lock.carrierPlan(),targetElapsed);int duration=(int)(time-burnoutTime);Vec3 approach=velocity.lengthSqr()<1E-8?new Vec3(0,0,1):velocity.normalize();double control=Math.min(120,Math.max(24,burnout.distanceTo(target)*.28));AntiAirRoute route=new AntiAirRoute(burnout,burnout.add(0,Math.min(96,control),0),target.subtract(approach.scale(control)),target,duration);double average=route.arcLength()/duration,peak=0;for(int i=0;i<=16;i++)peak=Math.max(peak,route.velocity(duration*i/16.0).length());if(target.isFinite()&&average<=AntiAirConstants.MAXIMUM_INTERCEPTOR_SPEED_BLOCKS_PER_TICK&&peak<=AntiAirConstants.MAXIMUM_INTERCEPTOR_SPEED_BLOCKS_PER_TICK)return Optional.of(new AntiAirInterceptSolution(time,target,velocity,route,average,peak));}return Optional.empty();}}